{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap (opening at the price, with any negotiated reduction supported by diligence and risk allocation)."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Prefer a deductible basket, or at minimum a tipping basket with a lower threshold and clear aggregation rules."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "Keep 18 months, if necessary, only as a negotiated period for ordinary warranties."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Require separate, robust capacity, ownership, title and no-encumbrance warranties."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud, deliberate concealment, title/fundamental matters and specific indemnities from general limitations."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure and constructive-knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit knowledge, if any, to actual knowledge of named individuals after defined inquiry; no deemed knowledge from advisers, data rooms or public records."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make receipt of final, unconditional written consent and satisfaction or waiver of all related conditions a condition precedent to completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment and discharge at completion from controlled funds flow, delivery of lender release documents and evidence that all security is released."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include them in the completion accounts or funds flow as an agreed deduction/retention, or have the Seller fund them before completion"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "The indemnity should cover the broader consequences of non-transfer, including replacement, remediation and third-party claims, rather than only the specified payment."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Obtain appropriate warranties and a specific indemnity for losses, response costs and regulatory exposure arising from the incident, with suitable cap and survival treatment."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "reflect any pre-completion liability or unusual commitment in completion accounts or a specific adjustment. Do not accept the Seller’s unsupported “ordinary-course” characterisation."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Align all clauses so the general limitations do not override negotiated carve-outs."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require completion evidence of transfer and any necessary releases."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Provide longer periods for tax and fundamental claims, and specific periods tied to the relevant risk for indemnities."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

